    /**
     * Method to retrieve the Merchant via MerchantFetchOneSummary
     * @param 	summary MerchantFetchOneSummary 
     * @return 	MerchantFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Merchant getMerchant( MerchantFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "MerchantFetchOneSummary arg cannot be null" );
    	
    	Merchant entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Merchant
        	// --------------------------------------
        	CompletableFuture<Merchant> futureEntity = queryGateway.query(new FindMerchantQuery( new LoadMerchantFilter( summary.getMerchantId() ) ), ResponseTypes.instanceOf(Merchant.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Merchant with id " + summary.getMerchantId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


